"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["74287"],{98041(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_distribuicao_vagas.modalidade_nao_admitida_pela_regra","status":422,"titulo":"Modalidade fora do rol que a regra de distribui\xe7\xe3o admite"},"descricao":{"codigo":"uniplus.selecao.configuracao_distribuicao_vagas.modalidade_nao_admitida_pela_regra","requisitos":["UNI-REQ-0140"],"oQueAconteceu":["A regra de distribui\xe7\xe3o de vagas referenciada declara um rol fechado de\\nmodalidades no `esquema_args` (`modalidades_admitidas`), e a oferta\\nselecionou ao menos uma modalidade fora desse rol. A regra **determina** o\\nconjunto de modalidades da oferta \u2014 n\xe3o \xe9 uma lista que o operador filtra\\nlivremente dentro dela.","`DISTRIB-VAGAS-INSTITUCIONAL` \xe9 a \xfanica regra de rol aberto: sem\\n`modalidades_admitidas` declarado, nada \xe9 restringido por esta confer\xeancia. As\\ndemais quatro regras declaram rol fechado \u2014 `DISTRIB-VAGAS-LEI-12711`,\\n`DISTRIB-VAGAS-LEI-12711-COM-AC-PCD`, `DISTRIB-VAGAS-PSIQ` e\\n`DISTRIB-VAGAS-COM-AC-PCD` \u2014 e qualquer modalidade fora do conjunto que\\ncada uma admite recai neste erro. A mensagem nomeia, dinamicamente, as\\nmodalidades que est\xe3o fora do rol."],"comoResolver":["Selecione, na oferta, apenas modalidades que o rol da regra escolhida\\nadmite. Se a distribui\xe7\xe3o precisa de uma modalidade fora desse rol, a regra\\nde distribui\xe7\xe3o est\xe1 errada para o caso \u2014 considere se a oferta n\xe3o \xe9, na\\nverdade, `DISTRIB-VAGAS-INSTITUCIONAL` (composi\xe7\xe3o livre, sem c\xe1lculo do\\nart. 10) ou outra varia\xe7\xe3o de rol mais amplo."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao distribuicao vagas"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);